package com.cgengine.math.affine;
import com.cgengine.math.Vector3f; import com.cgengine.model.*; import org.junit.jupiter.api.Test; import java.util.*; import static org.junit.jupiter.api.Assertions.*;
class ModelTransformTest { private static Model model(){Model m=new Model();m.vertices.addAll(List.of(new Vector3f(1,0,0),new Vector3f(0,1,0),new Vector3f(0,0,1)));Polygon p=new Polygon();p.setVertexIndices(new ArrayList<>(List.of(0,1,2)));m.polygons.add(p);m.computeNormals();return m;} @Test void resetRestoresOnlyTransformedModelAfterMultipleTrs(){Model a=model(),b=model();List<Vector3f> original=new ArrayList<>(a.vertices);a.applyTransformation(new Transformation(new Translator(2,3,4),Rotator.degrees(90,Rotator.Axis.Z),new Scaling(2,3,4)));a.applyTransformation(new Transformation(new Translator(-1,2,0)));a.resetTransformation();assertEquals(original,a.vertices);assertEquals(original,b.vertices);} @Test void floatDegreesAreConvertedCorrectly(){Model m=model();m.applyTransformation(new Transformation(Rotator.degrees(90,Rotator.Axis.Z)));assertEquals(0,m.vertices.getFirst().x(),.00001f);assertEquals(1,m.vertices.getFirst().y(),.00001f);} }
